function escapeRegExp(s: string): string {
  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function isWholePhrase(haystack: string, needle: string): boolean {
  const re = new RegExp('(?:^|[^a-z0-9])' + escapeRegExp(needle) + '(?:[^a-z0-9]|$)', 'i');
  return re.test(haystack);
}

